extern vec2 u_texelStep;
extern vec2 u_uvMin;
extern vec2 u_uvMax;
extern float u_time;

float paletteMask(vec3 rgb) {
  float e = 1.0 / 510.0;
  if (all(lessThanEqual(abs(rgb - vec3(195.0, 94.0, 94.0) / 255.0), vec3(e)))) return 1.0;
  if (all(lessThanEqual(abs(rgb - vec3(152.0, 61.0, 61.0) / 255.0), vec3(e)))) return 1.0;
  if (all(lessThanEqual(abs(rgb - vec3(102.0, 35.0, 35.0) / 255.0), vec3(e)))) return 1.0;
  if (all(lessThanEqual(abs(rgb - vec3(86.0, 31.0, 31.0) / 255.0), vec3(e)))) return 1.0;
  if (all(lessThanEqual(abs(rgb - vec3(62.0, 20.0, 20.0) / 255.0), vec3(e)))) return 1.0;
  if (all(lessThanEqual(abs(rgb - vec3(40.0, 11.0, 11.0) / 255.0), vec3(e)))) return 1.0;
  return 0.0;
}

float sampleMask(Image tex, vec2 uv) {
  float inside = step(u_uvMin.x, uv.x) * step(uv.x, u_uvMax.x)
    * step(u_uvMin.y, uv.y) * step(uv.y, u_uvMax.y);
  return inside * paletteMask(Texel(tex, uv).rgb);
}

float ringMask(Image tex, vec2 tc, float radius) {
  vec2 s = u_texelStep * radius;
  float m = sampleMask(tex, tc + vec2( s.x, 0.0));
  m = max(m, sampleMask(tex, tc + vec2(-s.x, 0.0)));
  m = max(m, sampleMask(tex, tc + vec2(0.0,  s.y)));
  m = max(m, sampleMask(tex, tc + vec2(0.0, -s.y)));
  m = max(m, sampleMask(tex, tc + vec2( s.x,  s.y)));
  m = max(m, sampleMask(tex, tc + vec2(-s.x,  s.y)));
  m = max(m, sampleMask(tex, tc + vec2( s.x, -s.y)));
  m = max(m, sampleMask(tex, tc + vec2(-s.x, -s.y)));
  return m;
}

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  float center = sampleMask(tex, tc);
  float nearGlow = ringMask(tex, tc, 1.0);
  float midGlow = ringMask(tex, tc, 2.0);
  float farGlow = max(ringMask(tex, tc, 3.0), ringMask(tex, tc, 4.0));
  float aura = max(nearGlow * 0.82, max(midGlow * 0.48, farGlow * 0.22));
  aura *= (1.0 - center);
  float pulse = 0.72 + 0.28 * (0.5 + 0.5 * sin(u_time * 4.6));
  float alpha = aura * pulse;
  return vec4(1.0, 0.68, 0.08, alpha) * color;
}

extern float u_time;
extern float u_flash;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec4 px = Texel(tex, tc);
  vec3 rgb = px.rgb;
  float e = 1.0 / 510.0;
  float goldMask = 0.0;
  if (all(lessThanEqual(abs(rgb - vec3(195.0, 94.0, 94.0) / 255.0), vec3(e))))
    { rgb = vec3(255.0, 255.0, 255.0) / 255.0; goldMask = 1.0; }
  else if (all(lessThanEqual(abs(rgb - vec3(152.0, 61.0, 61.0) / 255.0), vec3(e))))
    { rgb = vec3(255.0, 195.0, 0.0) / 255.0; goldMask = 1.0; }
  else if (all(lessThanEqual(abs(rgb - vec3(102.0, 35.0, 35.0) / 255.0), vec3(e))))
    { rgb = vec3(255.0, 151.0, 0.0) / 255.0; goldMask = 1.0; }
  else if (all(lessThanEqual(abs(rgb - vec3(86.0, 31.0, 31.0) / 255.0), vec3(e))))
    { rgb = vec3(182.0, 67.0, 54.0) / 255.0; goldMask = 1.0; }
  else if (all(lessThanEqual(abs(rgb - vec3(62.0, 20.0, 20.0) / 255.0), vec3(e))))
    { rgb = vec3(141.0, 44.0, 68.0) / 255.0; goldMask = 1.0; }
  else if (all(lessThanEqual(abs(rgb - vec3(40.0, 11.0, 11.0) / 255.0), vec3(e))))
    { rgb = vec3(108.0, 29.0, 48.0) / 255.0; goldMask = 1.0; }
  if (goldMask > 0.5) {
    float sweep = 0.5 + 0.5 * sin((tc.x + tc.y) * 135.0 - u_time * 5.5);
    float glint = pow(sweep, 18.0) * (0.55 + 0.25 * sin(u_time * 4.0));
    rgb = mix(rgb, vec3(1.0, 0.93, 0.56), clamp(glint, 0.0, 0.62));
  }
  rgb = mix(rgb, vec3(1.0, 0.94, 0.72), clamp(u_flash, 0.0, 1.0) * 0.22);
  return vec4(rgb, px.a) * color;
}

extern vec3 cIn1;
extern vec3 cOut1;
extern vec3 cIn2;
extern vec3 cOut2;
vec4 effect(vec4 color, Image tex, vec2 texture_coords, vec2 screen_coords) {
    vec4 texColor = Texel(tex, texture_coords);
    vec3 c = texColor.rgb;
    float d1 = distance(c, cIn1);
    float d2 = distance(c, cIn2);
    if (d1 < 0.05) { return color * vec4(cOut1, texColor.a); }
    if (d2 < 0.05) { return color * vec4(cOut2, texColor.a); }
    return color * texColor;
}

extern number u_time;     // seconds
extern number u_alpha;    // overlay opacity (0..1), masked by sprite alpha
extern vec2   u_dir;      // normalized drift direction in UV space
extern number u_cycle;    // seconds per full color cycle (3..5)
extern number u_scale;    // spatial scale of pattern
extern number u_grainScale; // grain density (screen-space)
extern number u_grainAmp; // grain strength (0..1)
extern number u_filmFreq; // thin-film interference frequency
extern number u_filmAmp;  // thin-film amplitude
extern number u_specular; // metallic/specular band strength
extern number u_fresnelPow; // fresnel shaping power (>=1)
extern vec4   u_frameUV;  // {minU, minV, sizeU, sizeV}; for fonts leave zeros to use tc
extern number u_colorGain; // overall color gain (1.0 = neutral)
extern number u_saturation; // color saturation multiplier (1.0 = neutral)
extern number u_mixBP;    // mix factor between wide and blue-purple palette (0..1)

vec3 palette(float x, vec3 a, vec3 b, vec3 c, vec3 d){
  return a + b * cos(6.28318 * (c * x + d));
}
float hash(vec2 p){
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  vec4 base = Texel(tex, tc) * color; // includes source alpha
  if (base.a <= 0.001) return vec4(0.0);
  float alpha = clamp(u_alpha, 0.0, 1.0) * base.a;
  if (alpha <= 0.0) return vec4(0.0);

  vec2 dir = u_dir;
  if (length(dir) < 0.001) dir = vec2(0.94, 0.34);
  else dir = normalize(dir);
  vec2 ortho = vec2(-dir.y, dir.x);
  vec2 tcL = tc;
  if (u_frameUV.z > 0.0 && u_frameUV.w > 0.0){
    tcL = (tc - u_frameUV.xy) / u_frameUV.zw;
    tcL = clamp(tcL, 0.0, 1.0);
  }
  float u = dot(tcL, dir) * u_scale + (u_time / max(u_cycle, 0.001));
  float v = dot(tcL, ortho) * u_scale;
  float grainLine = abs(sin(dot(tcL, ortho) * u_grainScale));
  float grainNoise = hash(tcL * 97.0 + vec2(13.3,7.7));
  float grain = mix(grainLine, grainNoise, 0.25);
  float film = u_filmAmp * (0.5 + 0.5 * sin(6.28318 * (u * u_filmFreq + grainNoise * 0.15)));
  float x = u + film;
  vec3 colBP = palette(x,
    vec3(0.55, 0.50, 0.58),
    vec3(0.25, 0.20, 0.28),
    vec3(1.00, 1.00, 1.00),
    vec3(0.10, 0.43, 0.78)
  );
  vec3 colWide = palette(u, vec3(0.52), vec3(0.12), vec3(1.0), vec3(0.00, 0.33, 0.66));
  vec3 foil = mix(colWide, colBP, clamp(u_mixBP, 0.0, 1.0));
  float band = 0.5 + 0.5 * sin(6.28318 * (u * 0.05 + v * 0.03));
  float fres = pow(0.5 + 0.5 * sin(6.28318 * v * 0.10), max(1.0, u_fresnelPow));
  float spec = u_specular * band * (0.2 + 0.8 * fres) * 0.15;
  float grainMul = 1.0 + u_grainAmp * (grain * 0.15 - 0.03);
  vec3 outRGB = foil * grainMul + spec;
  float Y = dot(outRGB, vec3(0.2126, 0.7152, 0.0722));
  outRGB = mix(vec3(Y), outRGB, max(0.0, u_saturation));
  outRGB *= max(0.0, u_colorGain);
  return vec4(outRGB, alpha);
}

extern vec4 sourceColors[5];
extern vec4 targetColors[5];
extern float threshold;
extern float u_mix; // Transition progress (0..1)

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
    vec4 texColor = Texel(tex, tc) * color;
    if (texColor.a < 0.01) return texColor;

    for (int i = 0; i < 5; i++) {
        if (distance(texColor.rgb, sourceColors[i].rgb) < threshold) {
            vec3 base = texColor.rgb;
            vec3 swapped = targetColors[i].rgb;
            // Gradually mix between original and stone-themed neutral gray
            return vec4(mix(base, swapped, u_mix), texColor.a);
        }
    }
    return texColor;
}

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  float a = Texel(tex, tc).a * color.a;
  if (a < 0.01) discard;
  return vec4(1.0);
}

extern float u_time;
extern float u_alpha;
extern float u_targetDpi;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  float a = Texel(tex, tc).a * color.a * clamp(u_alpha, 0.0, 1.0);
  vec2 logicalSc = sc / max(1.0, u_targetDpi);
  float p = (logicalSc.x * 0.055 + logicalSc.y * 0.040) + u_time * 3.8;
  float r = 0.64 + 0.36 * sin(p + 0.0);
  float g = 0.64 + 0.36 * sin(p + 2.094);
  float b = 0.64 + 0.36 * sin(p + 4.188);
  return vec4(r, g, b, a);
}

extern vec4 tintColor; // RGBA
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  float a = Texel(tex, tc).a;
  // Output solid tint color masked by source alpha
  return vec4(tintColor.rgb, tintColor.a * a);
}

extern float u_time;
extern vec2 u_center; // in window pixels
extern vec2 u_resolution;
extern float u_intensity;
// 0 = OriginStone, 1 = MileStone, 2 = BlessingStone
extern float u_stone_type;

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
    float minDim = min(u_resolution.y, u_resolution.x);
    vec2 uv = (sc.xy - u_center) / minDim;

    float dist     = length(uv);
    float rawAngle = atan(uv.y, uv.x);
    float t        = u_time;

    // ── Per-stone globals ──
    // OriginStone (0) + MileStone (1): small, simple, no micro-tendrils
    // BlessingStone (2): full organic deform
    bool isSimple = (u_stone_type < 1.5);  // Origin or Mile
    float warpAmp  = isSimple ? 0.45 : 1.0;
    float microAmp = isSimple ? 0.0  : 1.0;

    // ── Domain warp pass 1: large-scale organic deformation, pinned at origin ──
    float w1 = t * 0.52;
    float w2 = t * 0.37;
    vec2 warpUV = uv + dist * warpAmp * vec2(
        sin(uv.y * 2.6 + dist * 1.4 + w1) * 0.22 +
        cos(uv.x * 3.3 - dist * 1.9 + w2) * 0.14,
        cos(uv.x * 2.3 + dist * 1.7 - w1) * 0.18 +
        sin(uv.y * 3.8 + dist * 0.8 + w2) * 0.12
    );
    float wDist0 = length(warpUV);

    // ── Domain warp pass 2: medium wrinkles, pinned at origin ──
    vec2 warpUV2 = warpUV + wDist0 * warpAmp * vec2(
        sin(warpUV.y * 5.1 - dist * 3.2 + t * 0.81) * 0.08,
        cos(warpUV.x * 4.7 + dist * 2.8 - t * 0.64) * 0.07
    );
    float wDist1 = length(warpUV2);

    // ── Domain warp pass 3: fine local twist for Balatro-style curling tips ──
    vec2 warpUV3 = warpUV2 + wDist1 * warpAmp * vec2(
        cos(warpUV2.x * 8.3 + warpUV2.y * 3.7 - t * 1.20) * 0.04,
        sin(warpUV2.y * 7.1 - warpUV2.x * 4.2 + t * 0.95) * 0.04
    );

    float wDist = length(warpUV3);
    float angle = atan(warpUV3.y, warpUV3.x) + wDist * 3.4;

    // ── Layer A: primary 4-arm body (3 async sub-layers) ──
    float f1 = sin(angle * 4.0 + wDist *  8.5 + t * 2.10);
    float f2 = sin(angle * 4.0 - wDist *  6.2 - t * 1.73 + 1.05);
    float f3 = sin(angle * 4.0 + wDist * 11.0 + t * 2.90 + 2.09);
    // 2-arm sub-harmonic: asymmetric weight so the 4 arms breathe unevenly
    float fs = sin(angle * 2.0 + wDist * 4.8 - t * 1.40 + 0.52);
    float body = f1 * 0.38 + f2 * 0.32 + f3 * 0.22 + fs * 0.28;

    // ── Layer B: surface fiber texture (integer angular freq = no atan seam) ──
    float fd1 = sin(angle * 4.0 + wDist * 18.0 + t * 5.10);
    float fd2 = sin(angle * 8.0 - wDist * 14.0 - t * 3.80 + 1.80);
    float fd3 = sin(angle * 4.0 + wDist * 22.0 - t * 6.20 + 0.95);
    float fd4 = sin(angle * 8.0 + wDist * 30.0 + t * 7.50 + 3.14);
    float fiber = fd1 * 0.35 + fd2 * 0.28 + fd3 * 0.22 + fd4 * 0.15;

    // Mix body + fiber → raw signal
    float combo = body * 0.62 + fiber * 0.38;
    combo = combo * 0.5 + 0.5;   // remap to [0,1]

    // Narrow-band threshold → wide dark gaps, sharp arm edges (~4 arms)
    float mainShape = smoothstep(0.50, 0.80, combo);

    // ── Volumetric ribbon profile ──
    // ramp: 0 at arm center, 1 at flanks — gives Balatro-style thick glowing ribbons
    float armCenter = 0.65;
    float ramp = clamp(abs(combo - armCenter) * 3.2, 0.0, 1.0);
    float softCore = exp(-ramp * ramp * 3.5);        // wide luminous core
    float edgeRing = exp(-ramp * ramp * 14.0) * 0.6; // tight bright edge ring
    float volumetric = mainShape * (0.55 + softCore * 0.80 + edgeRing);

    // ── Layer C: micro sub-tendrils (2x warped space, finer branches) ──
    // Computed in a separately-warped coordinate so they feel independent
    vec2 microUV = warpUV2 * 2.1 + vec2(
        sin(t * 0.44 + wDist1 * 2.0) * wDist1 * 0.05,
        cos(t * 0.33 - wDist1 * 1.6) * wDist1 * 0.05
    );
    float mDist  = length(microUV);
    float mAngle = atan(microUV.y, microUV.x) + mDist * 2.8;
    float mb1 = sin(mAngle * 4.0 + mDist * 12.0 + t * 3.40);
    float mb2 = sin(mAngle * 4.0 - mDist *  9.0 - t * 2.60 + 1.57);
    float mb3 = sin(mAngle * 8.0 + mDist * 20.0 + t * 4.80 + 0.78);
    float micro = (mb1 * 0.45 + mb2 * 0.35 + mb3 * 0.20) * 0.5 + 0.5;
    float microShape = smoothstep(0.54, 0.76, micro) * 0.40 * microAmp;

    float finalShape = clamp(volumetric + microShape, 0.0, 1.8);

    // ── Per-stone radius scale ──
    // Origin + Mile: tighter radius; BlessingStone: full radius
    float radiusScale = isSimple ? 0.62 : 1.0;
    float outerEdge   = 1.10 * radiusScale;
    float innerEdge   = 0.30 * radiusScale;

    // ── Radial fades: hollow center + soft outer edge ──
    float innerFade = smoothstep(0.00, 0.18, dist);
    float outerFade = smoothstep(outerEdge, innerEdge, dist);
    finalShape *= innerFade * outerFade;

    // ── Origin + Mile: suppress overall brightness for simpler look ──
    if (isSimple) {
        finalShape *= 0.80;
    }

    // ── Prism color (all angular multipliers = integers → no seam) ──
    float p_val = wDist * 4.0 - rawAngle * 1.0 + t * 1.90;
    vec3 rainbow = vec3(
        0.5 + 0.5 * sin(p_val + 0.00),
        0.5 + 0.5 * sin(p_val + 2.09),
        0.5 + 0.5 * sin(p_val + 4.18)
    );
    // Per-arm hue shift: adjacent arms get different colour temperature
    float ctShift = sin(rawAngle * 2.0 + t * 0.80) * 0.30;
    rainbow = clamp(rainbow + ctShift * vec3(0.30, -0.08, 0.40), 0.0, 1.0);

    // ── OriginStone: desaturate to white/silver, gentle cool tint ──
    if (u_stone_type < 0.5) {
        float lum = dot(rainbow, vec3(0.299, 0.587, 0.114));
        rainbow = mix(vec3(lum), rainbow, 0.10) + vec3(0.05, 0.06, 0.12);
        rainbow = clamp(rainbow, 0.0, 1.0);
    }
    // ── MileStone: tint to #367f63 green, low saturation variation ──
    if (u_stone_type > 0.5 && u_stone_type < 1.5) {
        float lum = dot(rainbow, vec3(0.299, 0.587, 0.114));
        // #367f63 = (0.212, 0.498, 0.388) — blend desaturated base toward this hue
        vec3 mileGreen = vec3(0.212, 0.498, 0.388);
        rainbow = mix(vec3(lum) * mileGreen * 2.0, mileGreen, 0.55);
        // Allow a subtle luminance shimmer (lum variation preserves depth)
        rainbow *= 0.80 + 0.20 * lum;
        rainbow = clamp(rainbow, 0.0, 1.0);
    }
    // ── BlessingStone: gold (#ffc300) mixed with warm white ──
    if (u_stone_type > 1.5) {
        float lum = dot(rainbow, vec3(0.299, 0.587, 0.114));
        // #ffc300 = (1.0, 0.765, 0.0)
        vec3 gold  = vec3(1.00, 0.765, 0.00);
        vec3 warm  = vec3(1.00, 0.95,  0.80);  // soft warm white highlight
        // Core of arm → warm white; body → gold; blend by lum so bright parts gleam
        vec3 blessColor = mix(gold, warm, smoothstep(0.3, 0.85, lum));
        // Keep a tiny amount of the original luminance variation for depth
        blessColor *= 0.75 + 0.25 * lum;
        rainbow = clamp(blessColor, 0.0, 1.0);
    }

    // Core brighter & more saturated; edges tinted cooler/darker
    vec3 coreColor = rainbow * 2.0;
    vec3 edgeColor = rainbow * 0.80 + vec3(0.04, 0.02, 0.14);
    vec3 baseColor = mix(edgeColor, coreColor, softCore);

    // Sparkle: 2-axis shimmer — fine fibres catch light differently
    float shimmer = sin(wDist * 26.0 + t * 8.0) * sin(angle * 6.0 + t * 3.2);
    shimmer = shimmer * 0.09 + 0.91;
    // Slow pulse that makes the whole effect breathe (Balatro-style energy)
    // Origin + Mile pulse slower and calmer; BlessingStone is more energetic
    float pulseFreq = isSimple ? 0.9 : 1.7;
    float pulseAmp  = isSimple ? 0.07 : 0.12;
    float pulse = (1.0 - pulseAmp) + pulseAmp * sin(t * pulseFreq + dist * 2.0);
    baseColor *= shimmer * pulse;

    vec3 finalCol = baseColor * finalShape * u_intensity;
    float alpha   = clamp(finalShape * u_intensity * 0.95, 0.0, 1.0);

    return vec4(finalCol, alpha);
}

extern vec2  texelStep;   // texture coord offset equal to 1 screen pixel
extern float threshold;  // alpha threshold
extern float radiusPx;   // outline radius in px
extern float u_time;     // elapsed seconds for color animation
extern float u_targetDpi;
// Prism unit outline formula (matches getPrismBorderShader in render.lua)
vec3 prismColor(vec2 sc, float t){
  vec2 logicalSc = sc / max(1.0, u_targetDpi);
  float p = (logicalSc.x * 0.06 + logicalSc.y * 0.04) + t * 1.5;
  return vec3(
    0.70 + 0.30 * sin(p + 0.0),
    0.65 + 0.35 * sin(p + 2.1),
    0.75 + 0.25 * sin(p + 4.2)
  );
}
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  float a0 = Texel(tex, tc).a;
  if (a0 <= threshold){
    vec2 s = texelStep;
    float a1 = Texel(tex, tc + vec2( s.x, 0.0)).a;
    float a2 = Texel(tex, tc + vec2(-s.x, 0.0)).a;
    float a3 = Texel(tex, tc + vec2(0.0,  s.y)).a;
    float a4 = Texel(tex, tc + vec2(0.0, -s.y)).a;
    float a5 = Texel(tex, tc + vec2( s.x,  s.y)).a;
    float a6 = Texel(tex, tc + vec2(-s.x, -s.y)).a;
    float a7 = Texel(tex, tc + vec2( s.x, -s.y)).a;
    float a8 = Texel(tex, tc + vec2(-s.x,  s.y)).a;
    float neighbor = max(max(max(a1,a2),max(a3,a4)), max(max(a5,a6),max(a7,a8)));
    if (radiusPx > 1.5){
      vec2 t = s * 2.0;
      float b1 = Texel(tex, tc + vec2( t.x, 0.0)).a;
      float b2 = Texel(tex, tc + vec2(-t.x, 0.0)).a;
      float b3 = Texel(tex, tc + vec2(0.0,  t.y)).a;
      float b4 = Texel(tex, tc + vec2(0.0, -t.y)).a;
      float b5 = Texel(tex, tc + vec2( t.x,  t.y)).a;
      float b6 = Texel(tex, tc + vec2(-t.x, -t.y)).a;
      float b7 = Texel(tex, tc + vec2( t.x, -t.y)).a;
      float b8 = Texel(tex, tc + vec2(-t.x,  t.y)).a;
      float neighbor2 = max(max(max(b1,b2),max(b3,b4)), max(max(b5,b6),max(b7,b8)));
      neighbor = max(neighbor, neighbor2);
    }
    if (neighbor > threshold){
      // Prism color using screen coords (same formula as prism unit border)
      vec3 col = prismColor(sc, u_time);
      return vec4(col, 1.0);
    }
  }
  return vec4(0.0);
}

extern vec2 texelStep;      // texture coord offset equal to 1 screen pixel
extern vec4 outlineColor;   // RGBA
extern float threshold;     // alpha threshold
extern float radiusPx;      // outline radius in px (1=1px)
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  float a0 = Texel(tex, tc).a;
  if (a0 <= threshold){
    vec2 s = texelStep;
    float a1 = Texel(tex, tc + vec2( s.x, 0.0)).a;
    float a2 = Texel(tex, tc + vec2(-s.x, 0.0)).a;
    float a3 = Texel(tex, tc + vec2(0.0,  s.y)).a;
    float a4 = Texel(tex, tc + vec2(0.0, -s.y)).a;
    float a5 = Texel(tex, tc + vec2( s.x,  s.y)).a;
    float a6 = Texel(tex, tc + vec2(-s.x, -s.y)).a;
    float a7 = Texel(tex, tc + vec2( s.x, -s.y)).a;
    float a8 = Texel(tex, tc + vec2(-s.x,  s.y)).a;
    float neighbor = max(max(max(a1,a2),max(a3,a4)), max(max(a5,a6),max(a7,a8)));
    if (radiusPx > 1.5){
      vec2 t = s * 2.0;
      float b1 = Texel(tex, tc + vec2( t.x, 0.0)).a;
      float b2 = Texel(tex, tc + vec2(-t.x, 0.0)).a;
      float b3 = Texel(tex, tc + vec2(0.0,  t.y)).a;
      float b4 = Texel(tex, tc + vec2(0.0, -t.y)).a;
      float b5 = Texel(tex, tc + vec2( t.x,  t.y)).a;
      float b6 = Texel(tex, tc + vec2(-t.x, -t.y)).a;
      float b7 = Texel(tex, tc + vec2( t.x, -t.y)).a;
      float b8 = Texel(tex, tc + vec2(-t.x,  t.y)).a;
      float neighbor2 = max(max(max(b1,b2),max(b3,b4)), max(max(b5,b6),max(b7,b8)));
      neighbor = max(neighbor, neighbor2);
    }
    if (radiusPx > 2.5){
      vec2 t = s * 3.0;
      float c1 = Texel(tex, tc + vec2( t.x, 0.0)).a;
      float c2 = Texel(tex, tc + vec2(-t.x, 0.0)).a;
      float c3 = Texel(tex, tc + vec2(0.0,  t.y)).a;
      float c4 = Texel(tex, tc + vec2(0.0, -t.y)).a;
      float c5 = Texel(tex, tc + vec2( t.x,  t.y)).a;
      float c6 = Texel(tex, tc + vec2(-t.x, -t.y)).a;
      float c7 = Texel(tex, tc + vec2( t.x, -t.y)).a;
      float c8 = Texel(tex, tc + vec2(-t.x,  t.y)).a;
      float neighbor3 = max(max(max(c1,c2),max(c3,c4)), max(max(c5,c6),max(c7,c8)));
      neighbor = max(neighbor, neighbor3);
    }
    if (neighbor > threshold){ return outlineColor; }
  }
  return vec4(0.0);
}

extern vec2 texelStep;      // texture coord offset equal to 1 screen pixel
extern vec4 outlineColor;   // RGBA
extern float threshold;     // alpha threshold
extern float radiusPx;      // 1 = 1px, 2 = 2px
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  float a0 = Texel(tex, tc).a;
  if (a0 <= threshold){
    vec2 s = texelStep;
    float a1 = Texel(tex, tc + vec2( s.x, 0.0)).a;
    float a2 = Texel(tex, tc + vec2(-s.x, 0.0)).a;
    float a3 = Texel(tex, tc + vec2(0.0,  s.y)).a;
    float a4 = Texel(tex, tc + vec2(0.0, -s.y)).a;
    float a5 = Texel(tex, tc + vec2( s.x,  s.y)).a;
    float a6 = Texel(tex, tc + vec2(-s.x, -s.y)).a;
    float a7 = Texel(tex, tc + vec2( s.x, -s.y)).a;
    float a8 = Texel(tex, tc + vec2(-s.x,  s.y)).a;
    float neighbor = max(max(max(a1,a2),max(a3,a4)), max(max(a5,a6),max(a7,a8)));
    // Optional 2px radius: sample at 2*step
    if (radiusPx > 1.5){
      vec2 t = s * 2.0;
      float b1 = Texel(tex, tc + vec2( t.x, 0.0)).a;
      float b2 = Texel(tex, tc + vec2(-t.x, 0.0)).a;
      float b3 = Texel(tex, tc + vec2(0.0,  t.y)).a;
      float b4 = Texel(tex, tc + vec2(0.0, -t.y)).a;
      float b5 = Texel(tex, tc + vec2( t.x,  t.y)).a;
      float b6 = Texel(tex, tc + vec2(-t.x, -t.y)).a;
      float b7 = Texel(tex, tc + vec2( t.x, -t.y)).a;
      float b8 = Texel(tex, tc + vec2(-t.x,  t.y)).a;
      float neighbor2 = max(max(max(b1,b2),max(b3,b4)), max(max(b5,b6),max(b7,b8)));
      neighbor = max(neighbor, neighbor2);
    }
    if (neighbor > threshold){ return outlineColor; }
  }
  return vec4(0.0);
}

extern number time;
extern vec4 rayColor;
extern number density; // Number of rays
extern number speed;   // Rotation speed
extern number pixelSize; // Pixelation factor

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
    // Pixelate coordinates for that blocky feel
    vec2 p_tc = floor(tc * pixelSize) / pixelSize;

    // Adjust UV to squash vertically and SCALE UP (making the effect smaller)
    vec2 uv = (p_tc - 0.5) * 2.5;
    uv.y *= 2.0; // Squash vertically

    // Convert to polar
    float angle = atan(uv.y, uv.x);
    float dist = length(uv);

    // Rotation
    float rotAngle = angle + time * speed;

    // Sharp stepped rays
    float rayValue = sin(rotAngle * density);
    float ray = step(0.2, rayValue);

    // Radial fade (adjusted for the smaller size)
    float fade = 1.0 - smoothstep(0.0, 0.8, dist);

    // ADDITIVE BLENDING SIMULATION: Boost the output color significantly
    // This ensures it glows and stays bright even against dark backgrounds
    vec4 finalColor = rayColor * ray * fade * 2.0;
    finalColor.a = rayColor.a * ray * fade;

    return finalColor;
}

